type Run=<T>(fn:()=>T,msg?:string)=>T|null;
const title=(v:string)=>v.replace(/[-_]/g," ").replace(/\b\w/g,c=>c.toUpperCase());
const pct=(v:number|null)=>v==null?"No data":`${Math.round(v*100)}%`;
const clock=(ms:number)=>{const n=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(n/60)).padStart(2,"0")}:${String(n%60).padStart(2,"0")}`};
